3	import { useEffect, useRef, useState } from "react";
4	import Link from "next/link";
5	import { Capacitor } from "@capacitor/core";
6	import { buildReceiptPrintJob } from "../../actions";
7	import { dispatchPrintJobs } from "@/lib/dispatch-print-jobs";
8	
9	type Printer = { id: string; name: string };
10	
11	type NativeState =
12	  | { status: "idle" }
13	  | { status: "sending" }
14	  | { status: "ok" }
15	  | { status: "error"; message: string };
16	
17	export default function PrintButton({
18	  businessId,
19	  transactionId,
20	  printers,
21	}: {
22	  businessId: string;
23	  transactionId: string;
24	  printers: Printer[];
25	}) {
26	  // Struk dibuka dari POS lewat link baru (target="_blank") khusus untuk
27	  // dicetak — auto-buka dialog print begitu halaman selesai render, supaya
28	  // kasir tidak perlu klik "Cetak" lagi secara manual. Guard `printed` biar
29	  // tidak dobel kepanggil (mis. React StrictMode di dev me-render efek 2x).
30	  const printed = useRef(false);
31	  useEffect(() => {
32	    if (printed.current) return;
33	    printed.current = true;
34	    window.print();
35	  }, []);
36	
37	  // window.print() lewat print service Android tidak jalan untuk printer
38	  // thermal ESC/POS biasa (mis. Bluetooth RPP02N) — di app native, tawarkan
39	  // jalur alternatif: kirim struk (dengan harga) langsung ke printer yang
40	  // sudah diatur di Printer Dapur & Bar, sama seperti tiket dapur.
41	  const isNative = Capacitor.isNativePlatform();
42	  const [state, setState] = useState<Record<string, NativeState>>({});
43	
44	  async function handlePrintToPrinter(printer: Printer) {
45	    setState((s) => ({ ...s, [printer.id]: { status: "sending" } }));
46	    try {
47	      const built = await buildReceiptPrintJob(businessId, transactionId, printer.id);
48	      if (!built.success) {
49	        setState((s) => ({ ...s, [printer.id]: { status: "error", message: built.error } }));
50	        return;
51	      }
52	      const [result] = await dispatchPrintJobs(businessId, [built.job]);
53	      if (result?.result.ok) {
54	        setState((s) => ({ ...s, [printer.id]: { status: "ok" } }));
55	      } else {
56	        setState((s) => ({
57	          ...s,
58	          [printer.id]: {
59	            status: "error",
60	            message: result && !result.result.ok ? result.result.error : "Gagal mengirim.",
61	          },
62	        }));
63	      }
64	    } catch (err) {
65	      setState((s) => ({
66	        ...s,
67	        [printer.id]: { status: "error", message: err instanceof Error ? err.message : String(err) },
68	      }));
69	    }
70	  }
71	
72	  return (
73	    <div className="space-y-2">
74	      <div className="flex gap-2">
75	        <Link
76	          href={`/business/${businessId}/transactions/${transactionId}`}
77	          className="flex flex-1 items-center justify-center rounded-xl border border-zinc-200 bg-white py-2.5 text-sm font-medium text-zinc-600 hover:bg-zinc-50"
78	        >
79	          ← Kembali
80	        </Link>
81	        <button
82	          onClick={() => window.print()}
83	          className="flex-1 rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white hover:bg-brand-700"
84	        >
85	          🖨️ Cetak
86	        </button>
87	      </div>
88	
89	      {isNative && printers.length > 0 && (
90	        <div className="rounded-xl border border-zinc-200 bg-white p-3">
91	          <p className="mb-2 text-[11px] font-semibold text-zinc-500">
92	            Atau kirim langsung ke printer (untuk printer thermal Bluetooth/LAN):
93	          </p>
94	          <div className="space-y-1.5">
95	            {printers.map((p) => {
96	              const s = state[p.id] ?? { status: "idle" as const };
97	              return (
98	                <div key={p.id}>
99	                  <button
100	                    onClick={() => void handlePrintToPrinter(p)}
101	                    disabled={s.status === "sending"}
102	                    className="w-full rounded-lg border border-zinc-200 bg-zinc-50 py-2 text-xs font-medium text-zinc-700 disabled:cursor-not-allowed disabled:opacity-60"
103	                  >
104	                    {s.status === "sending" ? "Mengirim…" : `🖨️ Cetak ke ${p.name}`}
105	                  </button>
106	                  {s.status === "ok" && (
107	                    <p className="mt-1 text-[11px] font-medium text-green-600">✅ Terkirim.</p>
108	                  )}
109	                  {s.status === "error" && (
110	                    <p className="mt-1 text-[11px] font-medium text-red-600">❌ Gagal: {s.message}</p>
111	                  )}
112	                </div>
113	              );
114	            })}
115	          </div>
116	        </div>
117	      )}
118	    </div>
119	  );
120	}
