1	"use client";
2	
3	import { useState } from "react";
4	import { buildKitchenReprintJobs } from "../actions";
5	import { dispatchPrintJobs } from "@/lib/dispatch-print-jobs";
6	
7	type State =
8	  | { status: "idle" }
9	  | { status: "sending" }
10	  | { status: "ok"; count: number }
11	  | { status: "empty" }
12	  | { status: "error"; message: string };
13	
14	export default function ReprintKitchenButton({
15	  businessId,
16	  transactionId,
17	}: {
18	  businessId: string;
19	  transactionId: string;
20	}) {
21	  const [state, setState] = useState<State>({ status: "idle" });
22	
23	  async function handleReprint() {
24	    setState({ status: "sending" });
25	    try {
26	      const built = await buildKitchenReprintJobs(businessId, transactionId);
27	      if (!built.success) {
28	        setState({ status: "error", message: built.error });
29	        return;
30	      }
31	      if (built.jobs.length === 0) {
32	        setState({ status: "empty" });
33	        return;
34	      }
35	      const results = await dispatchPrintJobs(businessId, built.jobs);
36	      const failed = results.filter((r) => !r.result.ok);
37	      if (failed.length > 0) {
38	        setState({
39	          status: "error",
40	          message: `${failed.length}/${results.length} printer gagal — masuk antrian retry otomatis di POS.`,
41	        });
42	        return;
43	      }
44	      setState({ status: "ok", count: results.length });
45	    } catch (err) {
46	      setState({ status: "error", message: err instanceof Error ? err.message : String(err) });
47	    }
48	  }
49	
50	  return (
51	    <div className="mt-2">
52	      <button
53	        type="button"
54	        onClick={() => void handleReprint()}
55	        disabled={state.status === "sending"}
56	        className="w-full rounded-xl border border-zinc-200 bg-white py-2.5 text-sm font-medium text-zinc-700 transition-colors hover:bg-zinc-50 disabled:cursor-not-allowed disabled:opacity-60"
57	      >
58	        {state.status === "sending" ? "Mengirim…" : "🍳 Cetak Ulang ke Dapur/Bar"}
59	      </button>
60	      {state.status === "ok" && (
61	        <p className="mt-1.5 text-xs font-medium text-green-600">
62	          ✅ Terkirim ke {state.count} printer.
63	        </p>
64	      )}
65	      {state.status === "empty" && (
66	        <p className="mt-1.5 text-xs text-zinc-400">
67	          Tidak ada printer dapur/bar yang cocok untuk item di transaksi ini.
68	        </p>
69	      )}
70	      {state.status === "error" && (
71	        <p className="mt-1.5 text-xs font-medium text-red-600">❌ {state.message}</p>
72	      )}
73	    </div>
74	  );
75	}
