43	function buildDonutSegments(entries: [string, number][], total: number) {
44	  const R = 28;
45	  const cx = 40;
46	  const cy = 40;
47	  // Satu metode = lingkaran penuh; path arc 360° akan degenerate (titik awal == akhir).
48	  if (entries.length === 1) {
49	    return [{ d: null, color: DONUT_PALETTE[0] }];
50	  }
51	  let angle = -Math.PI / 2;
52	  return entries.map(([, val], i) => {
53	    const sweep = (val / total) * 2 * Math.PI;
54	    const x1 = cx + R * Math.cos(angle);
55	    const y1 = cy + R * Math.sin(angle);
56	    const x2 = cx + R * Math.cos(angle + sweep);
57	    const y2 = cy + R * Math.sin(angle + sweep);
58	    const large = sweep > Math.PI ? 1 : 0;
59	    angle += sweep;
60	    return {
61	      d: `M${cx},${cy} L${x1},${y1} A${R},${R} 0 ${large},1 ${x2},${y2} Z`,
62	      color: DONUT_PALETTE[i % DONUT_PALETTE.length],
63	    };
64	  });
65	}
